<?= view('portal/partials/shell_start', ['pageTitle' => $request['reference_number'], 'activeSection' => 'overview', 'businessName' => $businessName]) ?>
<a class="portal-back" href="/portal">&larr; Overview</a><header class="portal-record-heading"><div><p class="eyebrow">QUOTE REQUEST</p><h1><?= esc($request['reference_number']) ?></h1><p>Submitted <?= esc(substr((string) $request['created_at'], 0, 10)) ?></p></div><span class="portal-status"><?= esc(\App\Models\QuoteRequestModel::STATUSES[$request['status']] ?? ucfirst($request['status'])) ?></span></header>
<section class="portal-detail"><h2>Project brief</h2><p class="portal-lead"><?= nl2br(esc($request['project_summary'])) ?></p><dl class="portal-detail-grid"><dt>Desired completion</dt><dd><?= $request['desired_completion_date'] ? esc($request['desired_completion_date']) : 'Not specified' ?></dd><dt>Budget</dt><dd><?= $request['budget_range'] ? esc($request['budget_range']) : 'Not specified' ?></dd><dt>Preferred contact</dt><dd><?= esc(ucfirst($request['preferred_contact'])) ?></dd><?php if ($request['additional_notes']): ?><dt>Additional notes</dt><dd><?= nl2br(esc($request['additional_notes'])) ?></dd><?php endif ?></dl></section>
<?php if ($services): ?><section class="portal-detail"><h2>Requested services</h2><ul class="portal-simple-list"><?php foreach ($services as $service): ?><li><strong><?= esc($service['service_name']) ?></strong><span><?= esc($service['service_summary']) ?></span></li><?php endforeach ?></ul></section><?php endif ?>
<?php if ($answers): ?><section class="portal-detail"><h2>Your answers</h2><dl class="portal-answers"><?php foreach ($answers as $answer): ?><dt><?= esc($answer['question_label']) ?></dt><dd><?php $value = $answer['answer_text']; if (! $value && $answer['answer_json']) { $decoded = json_decode($answer['answer_json'], true); $value = is_array($decoded) ? implode(', ', array_map('strval', $decoded)) : ''; } ?><?= $value ? nl2br(esc($value)) : '&mdash;' ?></dd><?php endforeach ?></dl></section><?php endif ?>
<?php if ($files): ?><section class="portal-detail"><h2>Attachments</h2><ul class="portal-file-list"><?php foreach ($files as $file): ?><li><a href="/portal/requests/<?= (int) $request['id'] ?>/files/<?= (int) $file['id'] ?>"><?= esc($file['original_name']) ?></a><span><?= esc(number_format((int) $file['size_bytes'] / 1024, 0)) ?> KB</span></li><?php endforeach ?></ul></section><?php endif ?>
<?= view('portal/partials/shell_end', ['businessName' => $businessName, 'contactEmail' => $contactEmail]) ?>
